(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0019.js"] = [{"id":"glyph-seal-60f0","script":"seal","character":"惰","reading":"duò","description":"duò：懒，懈怠，与勤”相对懒～。怠～。～性。～慢。将骄卒～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惰"},{"id":"glyph-seal-60f3","script":"seal","character":"想","reading":"xiǎng","description":"xiǎng：(1)动脑筋，思索感～。思～。～法。～象（配置组合而创造出新形象的心理过程）。～入非非。异～天开。幻～。\n(2)推测，认为～必。～见（由推想而知道）。～来（表示只是根据推测，不敢完全肯定）。～当然（凭主观推测，认为事情应该是这样）。不堪设～。\n(3)希望，打算休～。理～。～望。妄～。\n(4)怀念，惦记～念。朝思暮～。\n(5)像云～衣裳花～容。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-想"},{"id":"glyph-seal-60f4","script":"seal","character":"惴","reading":"zhuì","description":"zhuì：又忧愁，又恐惧～恐。～栗（恐惧发抖）。～～不安。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惴"},{"id":"glyph-seal-60f6","script":"seal","character":"惶","reading":"huáng","description":"huáng：恐惧～怖。～恐。～惧。～～。～惑（疑惧）。～窘。～遽。惊～。～～不可终日。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惶"},{"id":"glyph-seal-60f9","script":"seal","character":"惹","reading":"rě","description":"rě：招引，挑逗招～。～事。～气。～祸。～恼。～是生非。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惹"},{"id":"glyph-seal-6101","script":"seal","character":"愁","reading":"chóu","description":"chóu：忧虑忧～。～苦。～楚。～烦。～虑。～郁。～闷。～容。～绪。借酒浇～。多～善感。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-愁"},{"id":"glyph-seal-6106","script":"seal","character":"愆","reading":"qiān","description":"qiān：(1)罪过，过失～忒。～尤。罪～。\n(2)耽误～期。～滞。\n(3)过～伏（天气冷暖失调，多指大旱或酷暑，有变化无常的意思）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-愆"},{"id":"glyph-seal-6109","script":"seal","character":"愉","reading":"yú；tōu","description":"yú：和悦，快意～快。～悦。欢～。不～之色。\ntōu：古同偷”，苟且敷衍。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-愉"},{"id":"glyph-seal-610f","script":"seal","character":"意","reading":"yì","description":"yì：(1)心思～思。～见。～义。～味。～念。～志（为了达到既定目的而自觉努力的心理状态）。注～。同～。～在笔先。～在言外。\n(2)心愿，愿望～愿。愿～。～向。～图。～皆∶～。醉翁之～不在酒”。\n(3)人或事物流露的情态春～。诗～。惬～。情～。～境。\n(4)料想，猜想～料。～想。～外。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-意"},{"id":"glyph-seal-611a","script":"seal","character":"愚","reading":"yú","description":"yú：(1)傻，笨～人。～笨。～蠢。～鲁。～氓（愚蠢的人）。～昧（缺乏知识，文化落后）。～顽。～妄。～不可及。大智若～（有大智慧的人，不卖弄聪明，表面上好像很愚笨，亦作大智如愚”）。\n(2)欺骗，耍～弄人。为人所～。\n(3)谦辞，用于自称～兄。～见。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-愚"},{"id":"glyph-seal-611f","script":"seal","character":"感","reading":"gǎn","description":"gǎn：(1)觉出～触。～觉。～性。～知（客观事物通过感觉器官在人脑中的直接反映）。～官。\n(2)使在意识、情绪上起反应；因受刺激而引起的心理上的变化～动。～想。反～∶～。情～。敏～。～染。～召。～慨。～喟。～叹。自豪～。～人肺腑。百～交集。\n(3)对人家的好意表示谢意～谢。～恩。～激。～愧。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-感"},{"id":"glyph-seal-6120","script":"seal","character":"愠","reading":"yùn","description":"yùn：怒，怨恨～色。～容。～怒。～恼。人不知，而不～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-愠"},{"id":"glyph-seal-6124","script":"seal","character":"愤","reading":"fèn","description":"充盈,旺盛\n愤怒;怨恨。同忿”\n所以昭炯戒,激众愤\n⒈因不满意而激动发怒～怒。气～得很。激起公～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-愤"},{"id":"glyph-seal-6126","script":"seal","character":"愦","reading":"kuì","description":"闷,烦乱\n昏乱,神志不清\n愦kuì糊涂，昏乱昏～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-愦"},{"id":"glyph-seal-6127","script":"seal","character":"愧","reading":"kuì","description":"kuì：羞惭羞～。惭～。～色。～怍（惭愧）。～疚。～赧（因羞愧而脸红）。～悔。问心无～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-愧"},{"id":"glyph-seal-613f","script":"seal","character":"愿","reading":"yuàn","description":"大头\n⒈乐意～意。自～。心甘情～。\n⒉希望～望。如～。平生之～。\n⒊仰慕，羡慕名声日闻，天下～。\n⒋迷信者所谓\"对神佛许诺的酬谢\"莫许～。错还～。\n⒌老实，恭谨谨～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-愿"},{"id":"glyph-seal-6148","script":"seal","character":"慈","reading":"cí","description":"cí：(1)仁爱，和善～爱。～善。～悲。～祥。仁～。～和。～眉善目。\n(2)特指慈母”，多用于对人称自己的母亲家～。～闱。～颜。～命。\n(3)对父母的孝敬奉养孝子～孙。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-慈"},{"id":"glyph-seal-614a","script":"seal","character":"慊","reading":"qiè；qiàn","description":"qiàn：不满，怨恨。\nqiè：满足，满意。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-慊"},{"id":"glyph-seal-614e","script":"seal","character":"慎","reading":"shèn","description":"shèn：(1)小心，当心谨～。不～。～重（zhòng）。～言。～独（在独处时能谨慎不苟）。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-慎"},{"id":"glyph-seal-6151","script":"seal","character":"慑","reading":"shè","description":"威胁\n威动天地,声","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-慑"},{"id":"glyph-seal-6155","script":"seal","character":"慕","reading":"mù","description":"mù：(1)向往，敬仰～名。羡～。仰～。爱～。景～。敬～。\n(2)思念，依恋思～。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-慕"},{"id":"glyph-seal-6162","script":"seal","character":"慢","reading":"màn","description":"màn：(1)迟缓，速度小，与快”相对～车。～件。～腾腾。～条斯理。缓～。迟～。～性。\n(2)态度冷淡，不殷勤，不礼貌～待。轻～。傲～。怠～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-慢"},{"id":"glyph-seal-6167","script":"seal","character":"慧","reading":"huì","description":"huì：聪明，有才智聪～。智～。颖～。～黠（聪明而狡猾）。～心。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-慧"},{"id":"glyph-seal-6168","script":"seal","character":"慨","reading":"kǎi","description":"kǎi：(1)情绪激昂，愤激愤～。慷～。\n(2)叹息，叹气～叹。感～。\n(3)豪爽，不吝啬～允。～诺。～然。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-慨"},{"id":"glyph-seal-6170","script":"seal","character":"慰","reading":"wèi","description":"wèi：(1)使人心里安适～问。～劳。～勉（安慰鼓励）。～唁（慰问死者家属）。～留。～藉。安～。劝～。抚～。\n(2)心安～志（宽慰自己的心情）。宽～。欣～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-慰"},{"id":"glyph-seal-6175","script":"seal","character":"慵","reading":"yōng","description":"yōng：困倦，懒得动～困。～懒。～惰。～倦。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-慵"},{"id":"glyph-seal-6177","script":"seal","character":"慷","reading":"kāng","description":"kāng：〔～慨〕ａ．情绪激昂，如～～激昂”；ｂ．待人热诚，愿意用财物帮助人，如为人～～大方”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-慷"},{"id":"glyph-seal-618e","script":"seal","character":"憎","reading":"zēng","description":"zēng：恨，厌恶，嫌～恨。～恶。爱～。面目可～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-憎"},{"id":"glyph-seal-6194","script":"seal","character":"憔","reading":"qiáo","description":"qiáo：〔～悴〕a.黄瘦，脸色不好，如颜色～～，形容枯槁”。b.指艰难困苦，如民之～～于虐政”。\n〔～虑〕苦思。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-憔"},{"id":"glyph-seal-61a7","script":"seal","character":"憧","reading":"chōng","description":"chōng：心意不定。\n〔～～〕往来不定，摇曳不定，如人影～～”。\n〔～憬〕向往，如～～未来”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-憧"},{"id":"glyph-seal-61ac","script":"seal","character":"憬","reading":"jǐng","description":"jǐng：醒悟～悟。～然（醒悟的样子）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-憬"},{"id":"glyph-seal-61c8","script":"seal","character":"懈","reading":"xiè","description":"xiè：不紧张～怠。～劲。～气。松～。无～可击。常备不～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-懈"},{"id":"glyph-seal-61cb","script":"seal","character":"懋","reading":"mào","description":"mào：(1)勤奋努力。\n(2)古同茂”，盛大。\n(3)勉励，鼓励。\n(4)美。\n(5)高兴。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-懋"},{"id":"glyph-seal-61d1","script":"seal","character":"懑","reading":"mèn","description":"气愤不平\n⒈烦闷烦～。\n⒉愤慨愤～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-懑"},{"id":"glyph-seal-61e6","script":"seal","character":"懦","reading":"nuò","description":"nuò：软弱无能～夫。～弱。怯～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-懦"},{"id":"glyph-seal-61f5","script":"seal","character":"懵","reading":"měng","description":"měng：(1)一时的心乱迷糊。\n(2)无知。\n(3)欺骗。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-懵"},{"id":"glyph-seal-61ff","script":"seal","character":"懿","reading":"yì","description":"yì：美好（多指德行，指有关女子的）嘉言～行。～范。～德。～旨（皇后或太后的诏令）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-懿"},{"id":"glyph-seal-6206","script":"seal","character":"戆","reading":"gàng","description":"戆头戆脑\n憨厚而刚直\n益戆由来未觉贤,终须南去吊\n⒈〈方〉愣，呆，鲁莽～头～脑。\n⒉见zhuàng。\n⒈刚直～直。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戆"},{"id":"glyph-seal-6208","script":"seal","character":"戈","reading":"gē","description":"gē：(1)古代的一种兵器，横刃，用青铜或铁制成，装有长柄干（gān）～。倒（dǎo）～。枕～待旦。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戈"},{"id":"glyph-seal-620a","script":"seal","character":"戊","reading":"wù","description":"wù：天干的第五位，用作顺序第五的代称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戊"},{"id":"glyph-seal-620c","script":"seal","character":"戌","reading":"xū","description":"xū：(1)地支的第十一位，属狗。\n(2)用于计时～时（下午七点至九点）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戌"},{"id":"glyph-seal-620d","script":"seal","character":"戍","reading":"shù","description":"shù：军队防守卫～。～边。～守。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戍"},{"id":"glyph-seal-620e","script":"seal","character":"戎","reading":"róng","description":"róng：(1)古代兵器的总称。\n(2)军队，军事兵～。投笔从～（指文人从军）。～装。～马。\n(3)古代称兵车御～。\n(4)大～功。\n(5)称（方言，音如农”）～有良翰”。\n(6)中国古代称西部民族西～。～狄。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戎"},{"id":"glyph-seal-620f","script":"seal","character":"戏","reading":"xì","description":"假借为麾”。军队中的帅旗\n侧翼\n指歌舞杂技等的表演\n戏剧\n那明湖居本是个大戏园子,戏台\n⒉见xì。\n⒈玩耍～耍。儿～。游～。\n⒉嘲弄，开玩笑～弄。嘲～。前言～耳。\n⒊演剧或歌唱、舞蹈、杂技等表演～剧。～曲。演～。唱～。杂～。看～★～。木偶～。花鼓～。\n戏xī 1.通\"羲\"。 2.通\"巇\"。险峻。 3.古地名。\n戏huī 1.大将之旗。参见\"戏下\"。引申为指挥。\n戏suō 1.酒樽名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戏"},{"id":"glyph-seal-6210","script":"seal","character":"成","reading":"chéng","description":"chéng：(1)做好，做完～功。完～。～就。～事。～交。～立。～婚。～仁（儒家主张的成就仁德）。～人之美。玉～其事。\n(2)事物发展到一定的形态或状况～形。～性。～人。自学～才。蔚然～风。\n(3)变为长～。变～。\n(4)可以，能行～，就这么办。\n(5)称赞人能力强他办事麻利，真～。\n(6)够，达到一定数量～年累（lěi）月。\n(7)已定的，定形的～规。～俗。～见。～例。～竹在胸。\n(8)十分之一增产三～。\n(9)平定，讲和会于稷，以～宋乱”。\n(10)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-成"},{"id":"glyph-seal-6211","script":"seal","character":"我","reading":"wǒ","description":"wǒ：自称，自己，亦指自己一方～们。～见（我自己的看法）。～辈。～侪（我们）。自～。～盈彼竭。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-我"},{"id":"glyph-seal-6212","script":"seal","character":"戒","reading":"jiè","description":"jiè：(1)防备～心。～备。～严。～骄～躁。\n(2)革除不良嗜好～除。～烟。\n(3)佛教律条，泛指禁止做的事～刀。～尺。斋～。\n(4)准备～途。～装。\n(5)古同界”，界限。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戒"},{"id":"glyph-seal-6215","script":"seal","character":"戕","reading":"qiāng","description":"qiāng：杀害～害。自～。～杀。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戕"},{"id":"glyph-seal-6216","script":"seal","character":"或","reading":"huò","description":"huò：(1)也许，有时，表示不定的词～许。～者（a.也许；b.连词，用在叙述句里，表示选择关系。均亦单用或”）。～然。～则。\n(2)某人，有的人～告之曰。\n(3)稍微不可～缓。不可～忽。不可～缺。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-或"},{"id":"glyph-seal-6218","script":"seal","character":"战","reading":"zhàn","description":"脱我战时袍。\n⒉发抖，极其害怕～栗。打～‘～。胆～心惊。～ ～兢兢。\n①指导战争全局的计划和策略～略上要藐视敌人。\n②有关战争全局的～略物资。\n③〈喻〉决定全局的策略～略措施。\n①作战双方的接触线。\n②指某项工作系统或方面教育～线。思想～线。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-战"},{"id":"glyph-seal-621a","script":"seal","character":"戚","reading":"qī","description":"qī：(1)因婚姻联成的关系亲～。外～。～族。～友。\n(2)忧愁，悲哀～然。凄～。哀～。休～。\n(3)古代兵器，像斧。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戚"},{"id":"glyph-seal-621b","script":"seal","character":"戛","reading":"jiá","description":"jiá：(1)长矛。\n(2)敲，敲打。\n(3)常礼；常法。\n(4)刮。\n(5)象声词～然长鸣。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戛"},{"id":"glyph-seal-621f","script":"seal","character":"戟","reading":"jǐ","description":"jǐ：古代一种合戈、矛为一体的长柄兵器钩～。～指。铁～。青铜～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戟"},{"id":"glyph-seal-6221","script":"seal","character":"戡","reading":"kān","description":"kān：用武力平定叛乱～乱。～夷（平定、征服）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戡"},{"id":"glyph-seal-6222","script":"seal","character":"戢","reading":"jí","description":"jí：(1)收敛，收藏～翼。～影。载～干戈（把兵器收藏起来）。\n(2)止，停止～怒。～鳞（喻蓄志待时）。\n(3)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戢"},{"id":"glyph-seal-622c","script":"seal","character":"戬","reading":"jiǎn","description":"jiǎn：(1)剪除，剪灭。\n(2)尽～谷（尽善，吉祥语）。\n(3)福。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戬"},{"id":"glyph-seal-622e","script":"seal","character":"戮","reading":"lù","description":"lù：(1)杀～尸。杀～。\n(2)羞辱，侮辱～人（罪人）。～民（受刑罚的人）。～辱。～笑（耻笑）。\n〔～力〕合力，并力，如～～同心”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戮"},{"id":"glyph-seal-6234","script":"seal","character":"戴","reading":"dài","description":"dài：(1)加在头、面、颈、手等处～帽子。披星～月。～圆履方。不共～天。\n(2)尊奉，推崇，拥护～仰。爱～。拥～。感恩～德。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戴"},{"id":"glyph-seal-6237","script":"seal","character":"户","reading":"hù","description":"hù：(1)一扇门，门门～。窗～。～枢不蠹。夜不闭～。\n(2)人家～口。～主。门～之见（亦指派别上的成见）。\n(3)会计部门称账册上有业务关系的团体或个人～头。开～。\n(4)门第门当～头。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-户"},{"id":"glyph-seal-623e","script":"seal","character":"戾","reading":"lì","description":"lì：(1)暴恶暴～。\n(2)罪过，乖张罪～。乖～。\n(3)至鸢飞～天。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戾"},{"id":"glyph-seal-623f","script":"seal","character":"房","reading":"fáng","description":"fáng：(1)住人或放东西的建筑物～屋。～产。～舍。～租。库～。楼～。书～。\n(2)结构和作用类似房子的东西蜂～。莲～。心～。\n(3)量词两～儿媳。\n(4)家族的一支大～。长（zhǎng）～。\n(5)星名，二十八宿之一。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-房"},{"id":"glyph-seal-6240","script":"seal","character":"所","reading":"suǒ","description":"suǒ：(1)处，地方住～。哨～。场～。处～。\n(2)机关或其他办事的地方的名称研究～。派出～。\n(3)量词，指房屋一～四合院。\n(4)用在动词前，代表接受动作的事物～部（所率领的部队）。～谓（a.所说的；b.某些人所说的，含不承认意）。无～谓（不关紧要，不关心）。～有。各尽～能。～向无敌。有～不为而后可以有为。\n(5)用在动词前，与前面的为”或被”字相应，表示被动的意思为人～敬。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-所"},{"id":"glyph-seal-6241","script":"seal","character":"扁","reading":"biǎn；piān","description":"biǎn：(1)物体平而薄～豆。～担。～圆。～铲。\n(2)古同匾”，匾额。\npiān：小～舟。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扁"},{"id":"glyph-seal-6243","script":"seal","character":"扃","reading":"jiōng","description":"jiōng：(1)从外面关门的闩、钩等～键（锁钥）。\n(2)上闩，关门和门昼～。\n(3)门户步于山～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扃"},{"id":"glyph-seal-6247","script":"seal","character":"扇","reading":"shàn；shān","description":"shàn：(1)摇动生风取凉的用具～子。～坠（扇柄下端的装饰物）。～面儿。～形。\n(2)指板状或片状的屏门～。隔～。\n(3)量词，用于门窗等一～门。\nshān：(1)摇动扇子或其它东西，使空气加速流动成风用扇子～。\n(2)鼓动别人去做不应该做的事～动。～风点火。\n(3)用手掌打～耳光。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扇"},{"id":"glyph-seal-6248","script":"seal","character":"扈","reading":"hù","description":"hù：(1)随从～从。～驾（随从帝王的车驾）。\n(2)披，带～江离与辟芷兮”。\n(3)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扈"},{"id":"glyph-seal-6249","script":"seal","character":"扉","reading":"fēi","description":"fēi：(1)门扇柴～。荆～。窗～。\n(2)作用与门扇相似的～页（书刊封面之内印着书名、著者的一页）。心～（思考问题的门路）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扉"},{"id":"glyph-seal-624b","script":"seal","character":"手","reading":"shǒu","description":"shǒu：(1)人使用工具的上肢前端～心。棘～（形容事情难办，像荆棘刺手）。着（zhuó）～（开始做，动手）。～不释卷。\n(2)拿着人～一册。\n(3)亲自动手～稿。～迹。～令。～书（a.笔迹；b.亲笔书信）。\n(4)技能、本领～法（技巧，方法）。～段。留一～。\n(5)做某种事情或擅长某种技能的人国～。扒～。生产能～。\n(6)小巧易拿的～枪。～册。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-手"},{"id":"glyph-seal-624d","script":"seal","character":"才","reading":"cái","description":"有才能;有本领\n才力;才能\n①才能怀～不遇。\n②有才能的人奇～。\n③表示以前不久他昨天～走。\n⑤表示本来并不如此的新情况直到天亮，我～知道迷路了。\n⑥表示事情发生得晚或结束得晚你怎么～来\n⑦对比起来表示数量小，次数少，能力差等他刚来北京的时候～三岁。\n⑨姓。\n【才略】政治或军事上的才干和智谋～过人。\n【才气过人】才华超过一般人。\n【才识】才能和见识。\n【才思】指文艺创作的能力～敏捷。\n【才智】才能和智慧。\n【才子】具有很高才干的人。\n才zāi 1.语气词。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-才"},{"id":"glyph-seal-6251","script":"seal","character":"扑","reading":"pū","description":"进攻\n拂着;拂拭\n⒈拍，轻打～粉。～蝴蝶。～打帽上的尘土。\n⒉冲，猛打郁香～鼻。～向敌军。～灭苍蝇。\n⒊击为雷电所～。\n扑bǔ 1.见\"扑挑\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扑"},{"id":"glyph-seal-6253","script":"seal","character":"打","reading":"dǎ；dá","description":"dǎ：(1)击，敲，攻击～击。殴～。～杀。\n(2)放出，发出，注入，扎入～炮。～雷。～信号。～电报。\n(3)做，造～首饰。～家具。\n(4)拨动～算盘。\n(5)揭，破，凿开～破。～井。\n(6)举，提起～灯笼。～起精神。\n(7)涂抹，印，画～蜡。～戳子。\n(8)写出，开出～证明。\n(9)捆，扎～包裹。\n(10)合，结合～伙。～成一片。\n(11)获取，购取～水。～鱼。\n(12)除去～消。～杈。\n(13)定出，计算～算。～腹稿。\n(14)用，采用，使用～比喻。\n(15)玩，玩耍～球。\n(16)截，停，减，退～住。～价儿。\n(17)表示人体发出某种行为动作～手势。\n(18)进行某种活动，从事或担任某种工作～交道。～短工。\n(19)与某些动词结合，基本上保留原动词词义～扫。～扰。\n(20)自，从～哪儿来？\n挨；\ndá：量词，指十二个一～铅笔。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-打"},{"id":"glyph-seal-6254","script":"seal","character":"扔","reading":"rēng","description":"rēng：(1)抛，投掷～球。\n(2)丢弃，舍弃～弃。～掉。\n(3)强牵引攘臂而～之。\n(4)摧。\n(5)古同仍”，仍然。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扔"},{"id":"glyph-seal-6258","script":"seal","character":"托","reading":"tuō","description":"tuō：(1)用手掌承着东西两手～着下巴。\n(2)陪衬，铺垫衬～℃～。\n(3)承着器物的东西～盘。\n(4)寄，暂放～身;～迹（均指遁居深山寄身于世外，以逃避世事）。\n(5)请别人代办委～。拜～。嘱～。\n(6)借故推委或躲闪推～。～故。\n(7)信赖，凭借～名。～庇。\n(8)压强单位。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-托"},{"id":"glyph-seal-625b","script":"seal","character":"扛","reading":"káng；gāng","description":"káng：用肩膀承担～枪。\ngāng：两手举东西力能～鼎。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扛"},{"id":"glyph-seal-6263","script":"seal","character":"扣","reading":"kòu","description":"kòu：(1)用圈、环等东西套住或拢住；把门～上。\n(2)衣纽衣～。\n(3)绳结绳～儿。\n(4)把器物口朝下放或覆盖东西把碗～在桌上。\n(5)相符，符合～题（符合题义）。\n(6)强留～押。\n(7)从中减除～除。～发（fā）。\n(8)敲击～人心弦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扣"},{"id":"glyph-seal-6267","script":"seal","character":"执","reading":"zhí","description":"拿;持\n①拿；持。\n②掌握；保持。\n③主管；掌管。\n④选取。\n⑤控制；驾驭。\n⑥执行。\n【执一】专心一志。\n【执友】志同道合的朋友。\n【执中】遵守中正之道，不偏不倚，无过于不及。采取中间的态度。\n【执引】古代送葬时的一种礼节，送葬的宾客须挽牵引柩车的绳索。\n【执业】持书诵习。业，书版。\n【执礼】守礼，遵行礼节。\n【执行】\n①把政策法令或计划等付诸实施。\n②法律用语。公安机关为实现以发生法律效力的判决和裁定所进行的活动。即对刑事案件的被告人执行刑罚，对应负民事责任的当事人责令其履行义务。\n【执拗】固执倔强。\n【执照】由有关行政机关发给的准许作某种行业的凭证。如施工执照；驾驶执照。\n【执迷】固执不悟。\n【执意】坚持自己的意见。\n①拘捕。\n②拿;持。\n③持守。\n④主持;掌管。\n⑤控制;统御。\n⑥操持;从事。\n⑦行;施行。\n⑧固执;坚持。\n⑨依据;遵照。\n⑩判断。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-执"},{"id":"glyph-seal-626a","script":"seal","character":"扪","reading":"mén","description":"抚摸\n扪mén按，抚摸～足。～心自问。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扪"},{"id":"glyph-seal-626c","script":"seal","character":"扬","reading":"yáng","description":"⒈举起，高举～起。～鞭。～帆。\n⒉称颂赞～。颂～。表～。\n⒊振作士气不～。\n⒋显示～兵耀武。\n⒌容貌出众其貌不～。\n⒍飘动，翻腾飞～。风～电激。\n⒎播散，传播～场。～声。宣～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扬"},{"id":"glyph-seal-626e","script":"seal","character":"扮","reading":"bàn","description":"bàn：化装～演。打～。装～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扮"},{"id":"glyph-seal-6270","script":"seal","character":"扰","reading":"rǎo","description":"叨扰,指受人财物、饮食\n⒈打搅，侵搅打～。搅～。干～。\n⒉乱天下方～。\n⒊驯服，驯养～化牲畜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扰"},{"id":"glyph-seal-6276","script":"seal","character":"扶","reading":"fú","description":"fú：(1)搀，用手支持人或物，使不倒搀～。～正。～老携幼。\n(2)帮助，援助～养。～植。～危济困。\n(3)用手按着或把持着～梯。沙发～手。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扶"},{"id":"glyph-seal-627c","script":"seal","character":"扼","reading":"è","description":"è：(1)用力掐着，抓住～杀。～腕（用一只手握住另一只手，表示振奋、失意、惋惜等情绪）。力能～虎。\n(2)抓要点，简要～要。\n(3)把守，控制～制。～喉拊背（喻控制要害，制敌于死命）。\n(4)古同轭”，牛马等拉东西时架在脖子上的器具。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扼"},{"id":"glyph-seal-627f","script":"seal","character":"承","reading":"chéng","description":"chéng：(1)在下面接受，托着～重。～受。\n(2)担当，应允～担。～当。～包。～做。～认。\n(3)受到，蒙受～蒙。～恩（蒙受恩泽）。\n(4)继续，接联继～。～平（指社会比较持久安定的局面）。～前启后。\n(5)顺从，迎合奉～。～颜候色（顺着别人颜色办事）。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-承"},{"id":"glyph-seal-6280","script":"seal","character":"技","reading":"jì","description":"jì：才能，手艺～术。～巧。～艺。～能。～法。黔驴～穷。雕虫小～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-技"},{"id":"glyph-seal-6289","script":"seal","character":"抉","reading":"jué","description":"jué：剔出～择（挑选）。～摘（a.抉择；如～～真伪”；b.揭发指摘，如～～弊端”）。～剔。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抉"},{"id":"glyph-seal-628a","script":"seal","character":"把","reading":"bǎ；bà","description":"bǎ：(1)拿，抓住～酒（拿着酒杯）。～玩（拿着赏玩）。\n(2)控制，掌握～握。～舵。\n(3)看守～守。～门儿。\n(4)自行车、手推车等的手柄车～。\n(5)可以用手拿的小捆秫秸～儿。\n(6)专权，一手独揽～持大权。\n(7)从后托起小孩两腿使之大小便的动作～尿。\n(8)介词，义为拿，处置，致使你能～他怎么样。\n(9)量词。\n(10)结盟拜～子。～兄弟。\nbà：(1)物体上便于手拿的部分刀～儿。\n(2)被人作为说笑资料的言行话～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-把"},{"id":"glyph-seal-6291","script":"seal","character":"抑","reading":"yì","description":"yì：(1)压，压制～制。～止。压～。～强扶弱。～扬（a.音调的高低起伏；b.沉浮；c.褒贬）。\n(2)忧闷～郁。～塞（sè）。\n(3)文言连词（a.表选择，相当于或是、还是，如～或”；b.表转折，相当于可是、但是，如多则多矣，～君似鼠”）。\n(4)文言发语词～齐人不盟，若之何”。\n(5)古同噫”，叹词。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抑"},{"id":"glyph-seal-6292","script":"seal","character":"抒","reading":"shū","description":"shū：(1)发出，表达，倾吐～情。～怀。～愤。～发。各～己见。直～胸臆。\n(2)挹取，挹注。\n(3)古同纾”，解除。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抒"},{"id":"glyph-seal-6295","script":"seal","character":"投","reading":"tóu","description":"tóu：(1)抛，掷，扔（多指有目标的）～篮。～弹（dàn）。\n(2)跳进去～河。自～罗网。\n(3)放进去，送进去～入。～资。～标。\n(4)走向，进入～宿（找地方住宿）。～奔。～靠。～降。～师（从师学习）。～诉。\n(5)发向～射。～影。\n(6)寄，递送～递。～稿。\n(7)合～合。意气相～。\n(8)临，在…以前～明。～暮（天黑以前）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-投"},{"id":"glyph-seal-6297","script":"seal","character":"抗","reading":"kàng","description":"kàng：(1)抵御～击。～争。～拒。抵～。顽～。\n(2)拒绝～议。～上。～命。～税。\n(3)对等～衡（力量不相上下的对抗）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抗"},{"id":"glyph-seal-6298","script":"seal","character":"折","reading":"shé；zhē；zhé","description":"zhē：翻转，倒腾～腾。～跟头。～个儿。\n合；搭；装；\nzhé：(1)断，弄断～断。～桂（喻科举及第）。～戟沉沙（形容惨重的失败）。\n(2)幼年死亡夭～。\n(3)弯转，屈曲曲～。转～。周～。～中（对不同意见采取调和态度。亦作折衷”）。\n(4)返转，回转～返。\n(5)损失损兵～将。\n(6)挫辱～磨。挫～。百～不挠。\n(7)减少～寿（减少寿命）。～扣。\n(8)抵作，对换，以此代彼～合。～价（把实物折合成钱）。\n(9)心服～服（a.信服；b.说服）。\n(10)戏曲名词，杂剧一本分四折，一折等于后来的一出～子戏。\n(11)判决～狱。\n合；搭；装；\nshé：(1)断，绳子～了。\n(2)亏损～本生意。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-折"},{"id":"glyph-seal-629a","script":"seal","character":"抚","reading":"fǔ","description":"扶持;护持\n⒈扶持，保护，养育～养。～育。～其老弱。\n⒉慰问～恤。安～。优～。\n⒊按摩，轻轻地摸～摩。～摸。\n⒋拍，击～背。～掌欢笑。\n抚mó 1.仿效。 2.临摹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抚"},{"id":"glyph-seal-629b","script":"seal","character":"抛","reading":"pāo","description":"pāo：(1)投，扔～掷。～撒（亦作抛洒”）。～售。\n(2)舍弃，丢下～弃。～荒（任由土地荒芜，不继续耕种）。～却。～头露面。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抛"},{"id":"glyph-seal-629f","script":"seal","character":"抟","reading":"tuán","description":"集聚\n⒈将东西捏揉成团～饭团。～煤球。～纸团子。〈引〉结聚，集中国力～者强，国好言谈者削。\n⒉〈古〉通\"团\"。圆。\n抟zhuàn 1.卷之使紧。 2.量词。束;捆。\n抟zhuān 1.专一。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抟"},{"id":"glyph-seal-62a0","script":"seal","character":"抠","reading":"kōu","description":"抓牢\n⒈使用手指或细小的东西挖～个小孔。把钉子从壁缝中～出来。〈引〉向片面狭窄的方面去深求专～字眼。死～条文。\n⒉雕刻～花纹。\n⒊吝啬，小气此人太～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抠"},{"id":"glyph-seal-62a1","script":"seal","character":"抡","reading":"lún","description":"挥动或挥舞\n任意浪费家财\n猛拉\n抡动\n抡动他的手臂\n抡眉竖目","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抡"},{"id":"glyph-seal-62a4","script":"seal","character":"护","reading":"hù","description":"贯铁絙护之。\n爱护\n袒护;包庇\n⒈保卫，照顾～卫。～厂。～航。～理。保～。爱～。〈引〉掩盖，包庇莫～短。你不要～着他。\n①外交机构发给本国公民证明身份的执照，在进入另一国停留时使用。\n②旧时旅行或运货时所带的政府机关证明文件。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-护"},{"id":"glyph-seal-62a5","script":"seal","character":"报","reading":"bào","description":"闻死刑之报,君为流涕。\n报答,报酬\n②告诉～信。\n③回答～以微笑。\n④报答，用实际行动表示感谢～国。\n⑤报复～仇。\n⑥报应一～一还一～。\n⑦报纸日～、周～。\n⑧某些刊物画～、学～。\n⑨用文字报道消息或发表意见的某些东西喜～、黑板～。\n⑩电报发～机。\n【报偿】报答和补偿。\n【报仇雪恨】采取行动来打击仇人，解除怨恨。雪洗除。\n【报酬】因使用别人的人力、物力等而付给别人的钱或物一心工作，不计～。\n【报告文学】记叙性散文中通讯、特写等体裁的总称。取材于现实生活中具有典型意义的真人真事，进行适当的艺术加工，迅速及时地反映当时的事件，带有新闻性、政治性和\n文学性的特点。\n【报捷】报告好消息。\n【报警】向治安机关报告危急情况或向有关方面或人发出紧急信号～器。\n【报警系统】发生危险情况时报警的装置系统。通常是开环控制系统，由报警探测器和指示器两个部分组成。如电子报警系统等。\n【报人】新闻工作者。\n【报丧】把某人去世的消息通知死者的亲友。\n【报喜不报忧】只汇报成绩而不说缺点和问题。\n【报晓】用声音告诉人天亮了金鸡～。\n【报效】为报答恩情而为之尽力。～祖国。\n【报应】佛教用语。原指善有善报，恶有恶报，后来专指种恶因得恶果做坏事迟早会得到～的。\n报fù 1.急速。 2.往，去。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-报"},{"id":"glyph-seal-62a8","script":"seal","character":"抨","reading":"pēng","description":"pēng：弹（tán）劾～击（用评论来攻击对方的短处）。～弹（tán）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抨"},{"id":"glyph-seal-62ab","script":"seal","character":"披","reading":"pī","description":"pī：(1)覆盖在肩背上～星戴月。\n(2)穿戴～挂。～甲。\n(3)打开，散开～襟。～阅。～露（发表，公布，表露）。所向～靡。\n(4)劈开，裂开竹竿～了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-披"},{"id":"glyph-seal-62b1","script":"seal","character":"抱","reading":"bào","description":"bào：(1)用手臂围住拥～。～小孩儿∠～。～残守缺（形容保守，不知进取）。\n(2)围绕，环绕山环水～。～厦（房屋前面加出来的门廊，亦指后面毗连的小房子）。\n(3)胸怀愿望，志向～负。\n(4)心里存着，怀有～怨。～恨。～歉。～憾。～病。\n(5)密合衣服～身儿。\n(6)把他人的子女收养为自己的子女～养。\n(7)量词表示两臂合围的量一～草。\n(8)孵～窝。～小鸡。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抱"},{"id":"glyph-seal-62b5","script":"seal","character":"抵","reading":"dǐ","description":"dǐ：(1)挡，拒，用力对撑着～挡。～制。～抗。～赖。\n(2)顶撞，冲突，矛盾～触。\n(3)代替，相当，顶替～押。～偿。～充。～还（huán）。\n(4)到达～京。～临。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抵"},{"id":"glyph-seal-62bd","script":"seal","character":"抽","reading":"chōu","description":"chōu：(1)把中间的取出把信～出。\n(2)从事物中提出一部分～签。～调（diào）。～查。～头。～薪止沸。\n(3)吸～烟。～水。～泣。～咽。\n(4)概括～象。～演。\n(5)减缩～缩。\n(6)引出，长出～青。～芽。～穗。～纱。\n(7)用细长的、软的东西打用鞭子～。\n(8)痉挛～搐。～风。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抽"},{"id":"glyph-seal-62c2","script":"seal","character":"拂","reading":"fú；bì","description":"fú：(1)拭，掸去～拭。～尘。\n(2)轻轻擦过～晓。春风～面。微风～煦。\n(3)甩动，抖动～袖而去。\n(4)违背，不顺忠言～耳。～逆。\nbì：古同弼”，辅助。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拂"},{"id":"glyph-seal-62c7","script":"seal","character":"拇","reading":"mǔ","description":"mǔ：(1)手、脚的大指～指。\n(2)划拳（亦称猜拳”），酒令的一种～战。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拇"},{"id":"glyph-seal-62c8","script":"seal","character":"拈","reading":"niān","description":"niān：用手指搓捏或拿东西～须。～轻怕重。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拈"},{"id":"glyph-seal-62c9","script":"seal","character":"拉","reading":"lā；lá","description":"lā：(1)牵，扯，拽～车。～网。～下马（喻使某人下台）。\n(2)用车载运～货。\n(3)使延长～延。～伸。\n(4)排泄粪便～屎。\n(5)联络～拢。～帮结伙。\n(6)摧折摧枯～朽。\n(7)带领转移把部队～出去。\n(8)牵引乐器的某一部分使乐器发出声音～小提琴。\n(9)抚养子女～扯。\n(10)帮助他有困难，～他一把。\n推；\nlá：(1)割，用刀把东西切开一道缝或切断手上～了一个口子。\n(2)闲谈～话。～家常。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拉"},{"id":"glyph-seal-62ca","script":"seal","character":"拊","reading":"fǔ","description":"fǔ：(1)拍～掌大笑。\n(2)古同抚”，安抚，抚慰。\n(3)器物的柄。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拊"},{"id":"glyph-seal-62d3","script":"seal","character":"拓","reading":"tuò；tà；zhí","description":"tuò：(1)开辟，扩充～荒。开～。～展。～落（a.宽广；b.潦倒失意。亦作落拓”）。\n(2)以手推物孔子之劲，能～国门之关，而不肯以力闻”。\n(3)姓。\ntà：在刻铸有文字或图像的器物上，涂上墨，蒙上一层纸，捶打后使凹凸分明，显出文字图像来～印。～本。～片。\nzhí：古同摭”，拾取。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拓"},{"id":"glyph-seal-62d4","script":"seal","character":"拔","reading":"bá","description":"bá：(1)抽，拉出，连根拽出～腿。～草。～牙。～苗助长。\n(2)夺取军事上的据点连～数城。\n(3)吸出～毒。～火罐儿。\n(4)选取，提升提～。～擢。\n(5)超出，高出海～。挺～。～地（山、树、建筑物等高耸在地面上）。～尖儿。出类～萃。\n(6)把东西放在凉水里使变凉把西瓜放在冰水里～一～。\n(7)改变坚韧不～。心志不可～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拔"},{"id":"glyph-seal-62d6","script":"seal","character":"拖","reading":"tuō","description":"tuō：(1)牵引，拉，拽～车。～船。～累（lěi）。～儿带女。\n(2)耷拉着～着辫子。\n(3)延长时间～延。～欠。～债。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拖"},{"id":"glyph-seal-62d7","script":"seal","character":"拗","reading":"niù；ǎo；ào","description":"ǎo：弯曲使断，折竹竿～断了。\nào：不顺，不顺从～口。～口令。\nniù：固执，不驯顺执～。～不过他。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拗"},{"id":"glyph-seal-62d8","script":"seal","character":"拘","reading":"jū；gōu；jv","description":"jū：(1)逮捕或扣押～捕。～系。～留。～拿。～囚。～禁。～押。\n(2)限，限制～束。～谨。不～小节。\n(3)固执，不变通～泥。～礼。～迂。\ngōu：遮蔽凡为长者粪之礼，必加帚于箕上，以袂～而退”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拘"},{"id":"glyph-seal-62d9","script":"seal","character":"拙","reading":"zhuō","description":"zhuō：(1)笨，不灵巧笨～。弄巧成～。～劣。\n(2)谦辞，称自己的～作。～见。～笔。～著。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拙"},{"id":"glyph-seal-62db","script":"seal","character":"招","reading":"zhāo","description":"zhāo：(1)打手势叫人来～唤。～呼。～手上车。\n(2)用公开的方式使人来～集。～收。～纳。～贤。～聘。～兵买马。\n(3)应接～待宾客。\n(4)引来～惹。～引。～揽。～致。\n(5)承认自己的罪行～供。～认。不打自～。\n(6)同着3”①②。\n(7)摇动～摇（故意张大声势，引人注意）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-招"},{"id":"glyph-seal-62dc","script":"seal","character":"拜","reading":"bài","description":"bài：(1)表示敬意的礼节～手（古代男子跪拜礼的一种）。～忏。礼～。回～。\n(2)恭敬地～托。～谢。～读。～别。～谒（a.拜见；b.瞻仰陵墓、碑碣）。\n(3)行礼棕～年。～寿。\n(4)用一定的礼节授与某种名义或职位，或结成某种关系～将（jiàng）。～相（xiàng）。～师。～把子。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拜"},{"id":"glyph-seal-62df","script":"seal","character":"拟","reading":"nǐ","description":"类似;比拟\n⒈准备，打算～办。～往广州。\n⒉起草，初步设想～稿。～订。草～计划。\n⒊模仿，仿照模～。～制。\n⒋比，比划，用兵器作杀人的样子比～。举剑～之。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拟"},{"id":"glyph-seal-62e8","script":"seal","character":"拨","reading":"bō","description":"拨动东西;分开;拨开\n①手脚或棍棒等横着发力～开众人。\n②分出一部分发给；调配调～。\n③掉转～马回营。\n④量词。用于人的分组；伙下午来了一～人。\n【拨乱反正】澄清混乱，恢复正常。\n【拨冗】客套话。推开繁重的事务，挤出时间望～赐教。\n拨fá 1.大盾。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拨"},{"id":"glyph-seal-62e9","script":"seal","character":"择","reading":"zé","description":"⒈挑拣，挑选选～。～良友。不～手段。\n择yì 1.人名用字。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-择"},{"id":"glyph-seal-62ec","script":"seal","character":"括","reading":"kuò；guā","description":"kuò：(1)扎，束～发（束起头发）。～约肌。\n(2)包容包～。概～。总～。囊～。\nguā：榨取，搜求搜～（亦作搜刮”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-括"},{"id":"glyph-seal-62ee","script":"seal","character":"拮","reading":"jié；jiá","description":"jié：〔～据（jū）〕经济境况不好，缺少钱，困窘。\njiá：同戛”。有用长矛刺、逼之意。。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拮"},{"id":"glyph-seal-62ef","script":"seal","character":"拯","reading":"zhěng","description":"zhěng：援救，救助～救。～饥。～弊（救正弊病）。～民于水火之中。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拯"},{"id":"glyph-seal-62f1","script":"seal","character":"拱","reading":"gǒng","description":"gǒng：(1)两手抱拳上举，以表敬意～手。～揖。\n(2)两手合围～抱。～木。～璧。\n(3)环绕～卫。～护。～北（众星环卫北极星）。\n(4)耸起，隆起，弯曲成弧形～肩缩背。～顶。～门。～桥。\n(5)向上或向前推，顶动～芽。虫子～土。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拱"},{"id":"glyph-seal-62f3","script":"seal","character":"拳","reading":"quán","description":"quán：(1)屈指卷（juǎn）握起来的手～头（头”读轻声）。\n(2)徒手的武术～术。打～。太极～。～谱。～脚。\n(3)肢体弯曲～曲。～起腿来。\n(4)量词，用于拳头打人的动作打他几～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拳"},{"id":"glyph-seal-62fc","script":"seal","character":"拼","reading":"pīn","description":"pīn：(1)连合，凑合～凑。～音。～接。～写。七～八凑。\n(2)不顾一切地奋斗，豁出去～力。～刺。～搏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拼"},{"id":"glyph-seal-62fe","script":"seal","character":"拾","reading":"shí；shè","description":"shí：(1)捡，从地上拿起～草。～粪。～零（捡取某方面的零碎材料，常用于文章标题）。～取。俯～皆是。～人牙慧。\n(2)收，敛，整理收～。～掇。\n(3)十”的大写。\n(4)旧称射箭人穿在左臂上的皮制护袖。\n丢；\nshè：古同涉”，历，经由～级而上。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拾"},{"id":"glyph-seal-62ff","script":"seal","character":"拿","reading":"ná","description":"ná：(1)用手取，握在手里～笔。～枪。\n(2)掌握，把握～主意。～权。～手。\n(3)挟（xié）制～捏（故意刁难人，要挟人）。～大（自以为比别人强，看不起人，摆架子）。\n(4)侵蚀，侵害让药水～白了。\n(5)逮捕，捉～获。擒～。～问。\n(6)攻下，占领一定要把敌人的碉堡～下来。\n(7)介绍，引出对象，相当于把”我～你当亲人看待。\n(8)介词，引出所凭借的工具、材料、方法等，相当于用”～笔来写。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拿"},{"id":"glyph-seal-6301","script":"seal","character":"持","reading":"chí","description":"chí：(1)拿着，握住～笔。～枪。～牢（把稳）。\n(2)遵守不变坚～。～久。～操（保持节操）。～之以恒。\n(3)主张，掌管主～。～平。～国。～重。～之有故（立论有根据）。\n(4)对待，处理～身（对待自己）。～盈。～胜。\n(5)扶助支～。撑～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-持"},{"id":"glyph-seal-6302","script":"seal","character":"挂","reading":"guà","description":"挂字耳。”\n悬挂;下垂\n⒈悬，悬吊～图片。悬～。彩灯高～。\n⒉牵绊，勾住，惦记牵～。～钩。～怀。～记。\n⒊登记去～号。快～失。\n⒋粘上，附着裤子上～了一层泥。\n⒌量词。用于成串的东西两～葡萄。三～珠子。\n①喜庆日子悬挂彩绸。\n②作战中负伤流血。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挂"},{"id":"glyph-seal-6307","script":"seal","character":"指","reading":"zhǐ","description":"zhǐ：(1)手伸出的支体（脚趾亦作脚指”）手～。巨～（大拇指）。～甲。～纹。～印。屈～可数。\n(2)量词，一个手指的宽度下了三～雨。\n(3)（手指或物体尖端）对着，向着～着。～画。～南针。～手画脚。\n(4)点明，告知～导。～引。～正。～责。～控（指名控告）。～摘。～挥。～日可待。\n(5)直立，竖起令人发（fà）～（形容极为愤怒）。\n(6)意向针对～标。～定。\n(7)古同旨”，意义，目的。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-指"},{"id":"glyph-seal-6308","script":"seal","character":"挈","reading":"qiè","description":"qiè：(1)用手提着提～。提纲～领。\n(2)带，领～带。～眷。扶老～幼。\n(3)古同锲”，刻。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挈"},{"id":"glyph-seal-6309","script":"seal","character":"按","reading":"àn","description":"àn：(1)用手或手指压～铃。～键。～钮。～脉。～摩。\n(2)止住～捺。～耐。～压。\n(3)依照～照。～理。～例。～说。～质论价。\n(4)考查，研求～验（审查验证）。～察（稽查审察）。\n(5)（编者、作者等）在正文之外所加的说明或论断～语。编者～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-按"},{"id":"glyph-seal-6311","script":"seal","character":"挑","reading":"tiāo；tiǎo","description":"tiāo：(1)扁担等两头挂着东西，用肩担着～土。～夫（旧时以给人挑货物行李为业的人）。\n(2)挑的东西～担。\n(3)挖取～荠菜。\n(4)量词，用于成挑儿的东西一～儿白菜。\n(5)选，拣～选。～拣。～剔。～肥拣瘦。\n(6)古同佻”，佻达。\ntiǎo：(1)用竿子棍棒等的一头举起或支起～起帘子。\n(2)用条状物或有尖的东西拨开或弄出来～打。\n(3)拨弄，引动～拨。～动。～头。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挑"},{"id":"glyph-seal-631a","script":"seal","character":"挚","reading":"zhì","description":"古国名\n通贽”。见面礼","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挚"},{"id":"glyph-seal-631b","script":"seal","character":"挛","reading":"luán","description":"抽搐,痉挛;手足蜷曲不能伸直\n挛跪\n挛缩","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挛"},{"id":"glyph-seal-631e","script":"seal","character":"挞","reading":"tà","description":"引申为攻打\n拍打","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挞"},{"id":"glyph-seal-631f","script":"seal","character":"挟","reading":"jiā","description":"挟制\n⒈用胳膊夹住。\n⒉携同～带。\n⒊凭借权势或抓住对方弱点，强迫人服从～制。要～。\n⒋怀着，藏着～怨。～不信之心。\n挟jiā 1.同\"夹\"。夹取;夹住。 2.通\"浃\"。通达;和洽;周遍。 3.通\"梜\"。筷子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挟"},{"id":"glyph-seal-6320","script":"seal","character":"挠","reading":"náo","description":"搅,搅动\n⒈搅，搅动，扰乱～乱。阻～。\n⒉弯曲，屈服贞而不～。百折不～。\n⒊抓，搔～痒。\n挠rào 1.缠绕。 2.船桨。\n挠xiāo 1.见\"挠挑\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挠"},{"id":"glyph-seal-6324","script":"seal","character":"挤","reading":"jǐ","description":"排斥;排挤\n毁坏;损坏\n⒈用力压使排出～牙膏。～羊奶。\n⒉想法子腾出来～时间。\n⒊拥，推，紧挨拥～。车厢里～满了人。街上也是人～人。〈引〉排斥相互排～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挤"},{"id":"glyph-seal-6325","script":"seal","character":"挥","reading":"huī","description":"舞动;摇动\n挥刀奋斫。\n⒉散出，甩出～金如土。～汗如雨。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挥"},{"id":"glyph-seal-6328","script":"seal","character":"挨","reading":"āi；ái","description":"āi：(1)依次，顺次～门逐户。\n(2)靠近～近。肩～着肩。\n打；\nái：(1)遭受～打。～骂。\n(2)拖延～时间。～延。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挨"},{"id":"glyph-seal-632b","script":"seal","character":"挫","reading":"cuò","description":"cuò：(1)不顺利，失败～折。～败。～伤。～失。\n(2)按下，使音调降低抑扬顿～。\n(3)摧折。\n(4)书法用笔的一种。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挫"},{"id":"glyph-seal-632f","script":"seal","character":"振","reading":"zhèn","description":"zhèn：(1)搬动，挥动～动。～荡。～幅。～臂。～聋发聩（喻唤醒糊涂麻木的人）。\n(2)奋起，兴起～奋。～作。～兴（xīng）。～～有辞。\n(3)古同赈”，救济。\n(4)古同震”，威震。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-振"},{"id":"glyph-seal-6339","script":"seal","character":"挹","reading":"yì","description":"yì：(1)舀，把液体盛出来～取。～彼注兹。～注（喻从有余的地方取出来，以补不足）。\n(2)拉。\n(3)古同抑”，抑制，谦退。\n(4)古同揖”，作揖。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挹"},{"id":"glyph-seal-633a","script":"seal","character":"挺","reading":"tǐng","description":"tǐng：(1)笔直，突出笔～。～进。～拔。～立。～秀。～括（guā）（衣服、衣料等平整）。～劲（jìng）。\n(2)伸直，凸出～直。～起腰。\n(3)支撑～节（坚持节操）。\n(4)很～好。～香。\n(5)量词，用于挺直物一～机关枪。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挺"},{"id":"glyph-seal-633d","script":"seal","character":"挽","reading":"wǎn","description":"wǎn：(1)拉，牵引～弓。～留。\n(2)设法使局势好转或恢复原状～救。力～狂澜。\n(3)追悼死人～词。～联。～幛。\n(4)古同晚”，后来的。\n(5)同绾”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挽"},{"id":"glyph-seal-6349","script":"seal","character":"捉","reading":"zhuō","description":"zhuō：(1)抓，逮～拿。～奸。～贼。～弄。捕～。捕风～影。\n(2)握～笔。～刀（代人作文）。～襟见肘。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捉"},{"id":"glyph-seal-634b","script":"seal","character":"捋","reading":"lǚ；luō","description":"luō：(1)用手握着条状物，顺着移动、抚摩～起袖子。～桑叶。\n(2)用手轻轻摘取～取。\nlǚ：用手指顺着抹过去，整理～胡子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捋"},{"id":"glyph-seal-634c","script":"seal","character":"捌","reading":"bā","description":"bā：(1)八”的大写。\n(2)古同扒”，破裂，分开。\n(3)古代一种聚拢谷物的没有齿的耙。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捌"},{"id":"glyph-seal-634d","script":"seal","character":"捍","reading":"hàn","description":"hàn：(1)保卫，抵御～卫。～御。\n(2)古代射者左臂佩戴的皮制袖套。\n(3)古同悍”，强悍。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捍"},{"id":"glyph-seal-634e","script":"seal","character":"捎","reading":"shāo；shào","description":"shāo：(1)顺便给别人带东西～带。～话。～信。\n(2)掠拂风～鲪滴难开幌”。\n(3)芟除拔剑～罗网”。\nshào：(1)稍微向后倒退（多指骡马等）往后～。\n(2)退～色。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捎"},{"id":"glyph-seal-6350","script":"seal","character":"捐","reading":"juān","description":"juān：(1)舍弃，抛弃～弃。～生。～躯。\n(2)献助～资。～献。～助。募～。\n(3)旧时献钱得官职～官。～纳。\n(4)赋税的一种车～。房～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捐"},{"id":"glyph-seal-6355","script":"seal","character":"捕","reading":"bǔ","description":"bǔ：捉，逮～捉。～获。～杀。巡～。缉～。～风捉影。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捕"},{"id":"glyph-seal-635f","script":"seal","character":"损","reading":"sǔn","description":"损失;丧失\n⒈减少～去。有～。\n⒉伤害～伤。～害。～人利己。满招～，谦受益。\n⒊丧失～失。～兵折将。\n⒋用刻薄的话挖苦人这话太～人了。\n⒌刻薄狠毒又凶又～。手段真～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-损"},{"id":"glyph-seal-6361","script":"seal","character":"捡","reading":"jiǎn","description":"约束\n拾取;取\n清理\n察看;检查\n捡liǎn 1.拱手。 2.通\"敛\"。收敛。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捡"},{"id":"glyph-seal-6362","script":"seal","character":"换","reading":"huàn","description":"huàn：(1)给人东西同时从他那里取得别的东西交～。对～。～工。～文。兑～。\n(2)更改，变变～。更（gēng）～。～马（喻撤换担负某项职务的人，含贬义）。～样。～气。～言之（换句话说）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-换"},{"id":"glyph-seal-6363","script":"seal","character":"捣","reading":"dǎo","description":"冲击;攻打\n①用棍、杵之类砸、舂～蒜、～米。\n②捶打～衣服。\n③搅扰～乱。\n【捣鬼】暗中使用诡计。\n【捣毁】砸坏；击垮。\n捣chóu 1.丛集，稠密。参见\"捣蓍\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捣"},{"id":"glyph-seal-636d","script":"seal","character":"捭","reading":"bǎi","description":"bǎi：(1)两手左右旁击。\n(2)分开～阖（指用手段分化或拉拢）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捭"},{"id":"glyph-seal-636e","script":"seal","character":"据","reading":"jù；jv","description":"依靠,凭借\n根据\n⒈占，占有占～。盘～山洞。～为己有。\n⒉靠着，按着～栏杆。左手～膝。〈引〉依靠，凭借～险固守。\n⒊凭依，按照依～。引经～典。～理力争。\n⒋凭证凭～。证～。要收～。有根有～。\n⒍见jū。\n⒉见jū。\n据jǐ 1.搏击;爪持。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-据"},{"id":"glyph-seal-6376","script":"seal","character":"捶","reading":"chuí","description":"chuí：敲打～衣。～鼓。～打。～拓。～挞。～楚（古代的杖刑）。～胸顿足。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捶"},{"id":"glyph-seal-6377","script":"seal","character":"捷","reading":"jié","description":"jié：(1)战胜～音。报～。～报。\n(2)战胜所获献～。\n(3)快，迅速～速。～径（敏捷机巧）。快～。敏～。～足先登。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捷"},{"id":"glyph-seal-637b","script":"seal","character":"捻","reading":"niǎn；niē","description":"niǎn：(1)用手指搓转（zhuàn）～麻绳。\n(2)搓成的条状物灯～儿。\nniē：古同捏”，用拇指和其他手指夹住。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捻"},{"id":"glyph-seal-637d","script":"seal","character":"捽","reading":"zuó","description":"揪住，抓住；也指拔取。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-6380","script":"seal","character":"掀","reading":"xiān","description":"xiān：(1)揭起，打开～开。～涌。～起。～动。\n(2)发动，兴起～风鼓浪（喻煽动情绪，挑起事端）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掀"},{"id":"glyph-seal-6387","script":"seal","character":"掇","reading":"duō","description":"duō：(1)拾取；摘取～拾。～弄。\n(2)用双手拿（椅子，凳子），用手端。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掇"},{"id":"glyph-seal-6388","script":"seal","character":"授","reading":"shòu","description":"shòu：(1)给，与～予。～权。～命。～奖。～旗。～衔。～意。\n(2)教，传给～业。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-授"},{"id":"glyph-seal-6389","script":"seal","character":"掉","reading":"diào","description":"diào：(1)落下～泪。\n(2)减损，消失～色。～价儿。\n(3)遗失，遗漏这一行～了两个字。\n(4)回转（zhuǎn）～头。～转。\n(5)亿，引申为卖弄，耍～文。～俏。～以轻心。～臂而去。\n(6)对换～包。～换。\n(7)落在后面～队。\n(8)用在动词后表示动作完成改～。戒～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掉"},{"id":"glyph-seal-638a","script":"seal","character":"掊","reading":"póu；pǒu","description":"pǒu：(1)抨击～击。\n(2)破开，剖～斗（dǒu）折衡（毁弃斗和秤）。\npóu：(1)用手扒土。\n(2)聚敛～敛。～聚。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掊"},{"id":"glyph-seal-638c","script":"seal","character":"掌","reading":"zhǎng","description":"zhǎng：(1)手心，脚心～心。手～。脚～。鼓～。易如反～。\n(2)用巴掌打～嘴。\n(3)把握，主持，主管～管。～权。～勺。～柜。\n(4)鞋底或牲口蹄子底下的东西鞋～。马～儿。\n(5)姓。\n〔～故〕关于历史人物、典章制度等的故事或传说。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掌"},{"id":"glyph-seal-638f","script":"seal","character":"掏","reading":"tāo","description":"tāo：(1)挖～一个洞。\n(2)探取～钱。～腰包。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掏"},{"id":"glyph-seal-6390","script":"seal","character":"掐","reading":"qiā","description":"qiā：(1)用指甲按或截断～算。～花。～尖儿。\n(2)割断，截去～头去尾。\n(3)用手的虎口及手指紧紧握住一把～住。\n(4)量词，一只手或两只手指尖相对握着的数量一～儿松枝。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掐"},{"id":"glyph-seal-6392","script":"seal","character":"排","reading":"pái；pǎi","description":"pái：(1)除去，推开～出。～斥。～水。～外。～挤。～山倒海。～忧解难。\n(2)摆成行列～列。～队。～字。～印。～笔。～场。\n(3)排成的行列～头。前～。\n(4)军队的编制单位，班”的上一级。\n(5)练习演戏～戏。\n(6)竹或木平摆着编扎成的水上交通工具木～。竹～。～运。\npǎi：〔～子车〕用人力拉运东西的一种车，多用于运货。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-排"},{"id":"glyph-seal-6396","script":"seal","character":"掖","reading":"yè；yē","description":"yè：(1)用手扶着别人的胳膊扶～。\n(2)扶持别人～护。奖～。\n(3)古同腋”，旁边。\nyē：把东西塞在衣袋或夹缝里腰里～着手榴弹。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掖"},{"id":"glyph-seal-6398","script":"seal","character":"掘","reading":"jué","description":"jué：(1)刨，挖～土。～井。～进。发～。挖～。\n(2)古同崛”，崛起。\n(3)古同倔”，倔强。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掘"},{"id":"glyph-seal-63a0","script":"seal","character":"掠","reading":"lüě；lüè","description":"lüè：(1)夺取～夺。～取。抢～。劫～。\n(2)擦过～视。浮光～影。\n(3)拷打～笞。～治。拷～。\n(4)砍伐～林。\n(5)顺手抓取随手～起一根棍子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掠"},{"id":"glyph-seal-63a2","script":"seal","character":"探","reading":"tàn","description":"tàn：(1)寻求～求。～讨。～索。～试。勘～。试～。钻～。～幽访胜。～本穷源。\n(2)侦察打听～问。～听。～询。～查。～察。\n(3)做侦察工作的人～马（侦察骑兵）。敌～。密～。\n(4)访问，看望～望。～亲。～监。\n(5)头或上体伸出，手伸入～身。～头～脑。～囊取物。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-探"},{"id":"glyph-seal-63a5","script":"seal","character":"接","reading":"jiē","description":"jiē：(1)连成一体～合。～骨。～壤。衔～。\n(2)继续，连续～力。～替。～班。～二连三。再～再厉。\n(3)靠近，挨上～近。邻～。～吻。\n(4)承受，收取～受。～收。～纳。～管。\n(5)迎～风。～生。～待。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-接"},{"id":"glyph-seal-63a7","script":"seal","character":"控","reading":"kòng","description":"kòng：(1)告状，指出罪恶～告。～诉。指～。被～。\n(2)节制，驾驭～制。遥～。\n(3)开弓弓不再～。\n(4)投～于地。\n(5)人的头部朝下或使让残液流出容器的口朝下～净。～一～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-控"},{"id":"glyph-seal-63a8","script":"seal","character":"推","reading":"tuī","description":"tuī：(1)手抵物体向外或向前用力使物移动～车。～搡。～拿。～倒。～敲。顺水～舟。\n(2)使用工具向前移动进行工作～头。～土。\n(3)使事情开展～广。～行（xíng）。～动。～销。\n(4)进一步想，由已知之点想到其它～及。～究。～导。～论。～测。～事。\n(5)往后挪动（时间上）～延。～移。\n(6)辞让，脱卸～让。～却。～委。～辞。\n(7)举荐，指出某人优点～许。～重（zhòng）。～举。～崇。\n(8)让出，献出～恩。～心置腹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-推"},{"id":"glyph-seal-63a9","script":"seal","character":"掩","reading":"yǎn","description":"yǎn：(1)遮蔽，遮盖～护。～体。～饰。～映。～盖。～蔽。～埋。～人耳目。瑕不～瑜。藏瑕～疵。\n(2)关，合～闭。～门。～卷。\n(3)门、窗、箱柜等关合时夹住了东西～了手。\n(4)乘人不备而袭击或捉拿～杀。～击。～袭。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掩"},{"id":"glyph-seal-63aa","script":"seal","character":"措","reading":"cuò","description":"cuò：(1)安放，安排～手。～辞。～置。～身。\n(2)筹划办理～施。～办。筹～。举～失当。\n(3)弃置刑～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-措"},{"id":"glyph-seal-63ac","script":"seal","character":"掬","reading":"jū；jv","description":"jū：用两手捧以手～水。～诚相见。笑容可～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掬"},{"id":"glyph-seal-63b8","script":"seal","character":"掸","reading":"dǎn","description":"拂去\n中国史书上对傣族的一种称呼\n古国名\n掸 dǎn用掸子之类的东西轻轻拂扫或拍打，以去掉器物上的灰尘等～桌子、～衣服。又见shàn。\n【掸子】用鸡毛或布条等绑成的除去灰尘的用具。\n⒈〈古〉我国对傣族的称呼。\n掸chán 1.牵引。 2.相缠不去。参见\"掸掸\"。 3.调戏。\n掸tān 1.持不坚;瘫倒。\n掸dàn 1.触。 2.用同\"弹\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掸"},{"id":"glyph-seal-63ba","script":"seal","character":"掺","reading":"chān","description":"同参”。古时候的一种鼓曲名。也指击鼓三次\n细小\n同扦”。女手纤美的样子\n掺shǎn 1.执，操。 2.操守。\n掺shān 1.女手纤美貌。\n掺sēn 1.树木众盛貌。\n掺càn 1.古代鼓曲名。 2.指古代乐曲演奏中的一种击鼓之法。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掺"},{"id":"glyph-seal-63bc","script":"seal","character":"掼","reading":"guàn","description":"扔,摔,掷\n佩带;披带\n跌;使跌\n掼guàn〈方〉\n⒈扔，掷纸屑、果皮～到垃圾箱里。\n⒉摔，跌～跤。～倒了。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掼"},{"id":"glyph-seal-63be","script":"seal","character":"掾","reading":"yuàn","description":"古代官署中属员的通称，如掾属。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-63c4","script":"seal","character":"揄","reading":"yú","description":"yú：拉，引～长袂，蹑利屣”。\n〔～扬〕a.宣传，发扬，如～～大义”；b.赞扬，称赞，如极口～～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-揄"},{"id":"glyph-seal-63c6","script":"seal","character":"揆","reading":"kuí","description":"kuí：(1)度（duó），揣测～度。～策。～古察今。\n(2)道理，准则千载一～。\n(3)事务百～。\n(4)管理，掌管～百事。\n(5)旧称总揽政务的人，如宰相等阁～。～席（宰相之位）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-揆"},{"id":"glyph-seal-63d0","script":"seal","character":"提","reading":"tí；dī；dǐ","description":"tí：(1)垂手拿着有环、柄或绳套的东西～壶。～灯。～篮。～包。～盒。～纲挈领。\n(2)引领（向上或向前等）～心吊胆。～升。～挈。～携。\n(3)说起，举出～起。～出。～醒。～倡。～议。～名。～案。～要。\n(4)将犯人从关押之处带出来～审。～犯人。\n(5)率领，调遣～兵。\n(6)取出～取。～货。\n(7)汉字笔形之一，即挑。\n(8)舀取油、酒等液体的一种用具油～。酒～。\n(9)古代鼓名师帅执～”。\n(10)姓。\n降；\ndī：〔～防〕小心防备。\n降；\ndǐ：投掷荆轲废，乃引其匕首～秦王”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-提"},{"id":"glyph-seal-63d2","script":"seal","character":"插","reading":"chā","description":"chā：(1)扎进去，把细长或薄的东西放进去～入。～秧。～花。～座。～头。～翅难飞。\n(2)加入，参与～班。～话。～曲。～图。～页。～叙。安～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-插"},{"id":"glyph-seal-63d6","script":"seal","character":"揖","reading":"yī","description":"yī：古代的拱手礼作（zuō）～。～让（宾主相见的礼节）。～客。～别。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-揖"},{"id":"glyph-seal-63e0","script":"seal","character":"揠","reading":"yà","description":"yà：拔～苗助长（zhǎng）（亦称拔苗助长”）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-揠"},{"id":"glyph-seal-63e1","script":"seal","character":"握","reading":"wò","description":"wò：(1)手指弯曲合拢，执持～手。～拳。～别。把～。掌～。～力。～笔。～管。～瑜（喻怀有美好的才德）。\n(2)量词，指一把大小或分量一～粗。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-握"},{"id":"glyph-seal-63e3","script":"seal","character":"揣","reading":"chuāi；chuǎi；chuài；tuán；zhuī","description":"chuǎi：(1)估量，忖度～测。～摩。～度（duó）。～想。～情（忖度情理）。不～冒昧。\n(2)姓。\nchuài：〔挣（zhèng）～〕见挣1”。\n〔囊（nāng）～〕见囊1”。\nchuāi：放在衣服里～着手。～在怀里。\ntuán：古同团”，聚集的样子。\nzhuī：捶击～而锐之，不可长保”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-揣"},{"id":"glyph-seal-63ea","script":"seal","character":"揪","reading":"jiū","description":"jiū：用手抓住或扭住～住。～心。～辫子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-揪"},{"id":"glyph-seal-63ed","script":"seal","character":"揭","reading":"jiē；qì","description":"jiē：(1)把盖在上面的东西拿起，或把粘合着的东西分开～锅。～幕。\n(2)使隐瞒的事物显露～露。～发。～底。～穿。～短。～晓。\n(3)高举～竿而起。\n(4)标示～橥（zhū）（本是作标记的小木桩，引申为标志。亦作揭著”）。～示。\n(5)扛，持。\n(6)姓。\n掀；\n捂；盖；\nqì：提起衣裳～衣涉水。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-揭"},{"id":"glyph-seal-63f4","script":"seal","character":"援","reading":"yuán","description":"yuán：(1)牵引攀～。～之以手。\n(2)帮助，救助支～。～外。～助。～军。～救。增～。孤立无～。\n(3)引用～用。～引。～据。\n(4)执，持～笔（拿起笔来写，如～～而书”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-援"},{"id":"glyph-seal-6400","script":"seal","character":"搀","reading":"chān","description":"混杂;搀和\n①搀扶让我～你一把。\n②把一种东西混入另一种东西里～沙子、～假。\n【掺兑】把成分不同的东西混合在一起把白面和玉米面～在一起蒸丝糕。\n⒈挽，牵扶～扶。手～手。～着老大娘走人行道。\n⒉混合～杂。～点糖。不能～沙子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-搀"},{"id":"glyph-seal-6402","script":"seal","character":"搂","reading":"lǒu","description":"搂抱;用手或工具把东西向自己面前聚集\n兜揽\n核算\n用手拢着提\n⒈将东西聚拢起来～草。～柴。\n⒉搜刮贪官污吏专会～钱。\n⒊用手指往怀里拨、扳～手枪。～机枪。\n⒈两臂合抱，向怀里拢着～抱。～着孩子。\n⒉量词三～草。两～粗的银杏树。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-搂"},{"id":"glyph-seal-6405","script":"seal","character":"搅","reading":"jiǎo","description":"混合;拌合;搅拌\n胡闹;嬉戏\n⒈扰乱，打扰莫～乱。别～扰。\n⒉拌和～拌。～匀。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-搅"},{"id":"glyph-seal-640f","script":"seal","character":"搏","reading":"bó","description":"bó：(1)对打～斗。～击（奋力进击）。～战。～膺（捶胸，表示愤怒）。肉～。拼～。\n(2)跳动～动。脉～。\n(3)捕捉～噬。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-搏"},{"id":"glyph-seal-6414","script":"seal","character":"搔","reading":"sāo","description":"sāo：(1)挠，用手指甲轻刮～痒。～头。隔靴～痒。\n(2)古同骚”，扰乱。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-搔"},{"id":"glyph-seal-641c","script":"seal","character":"搜","reading":"sōu","description":"sōu：(1)寻求，寻找～集。～寻。～求。～讨。～罗。～刮。～索枯肠。\n(2)检查～查。～身。～腰。～捕。～索。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-搜"},{"id":"glyph-seal-6426","script":"seal","character":"搦","reading":"nuò","description":"nuò：(1)握，持，拿着～管（执笔）。\n(2)按下。\n(3)摩。\n(4)挑惹～战（挑战）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-搦"},{"id":"glyph-seal-6434","script":"seal","character":"搴","reading":"qiān","description":"qiān：拔取斩将～旗。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-搴"},{"id":"glyph-seal-643a","script":"seal","character":"携","reading":"xié","description":"xié：(1)带～手。～带。扶老～幼。\n(2)离，叛离～离。～贰。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-携"},{"id":"glyph-seal-6444","script":"seal","character":"摄","reading":"shè","description":"执;持\n拘捕\n辅助、佐助\n摄,佐也。╠\n⒉代理，辅助～政。～位。\n⒊保养～生。珍～。\n⒋撩起，整理～帘。～衣。\n⒌收敛～绳。\n摄niè 1.安定。\n摄shà 1.古代祭祀之位，形似腰扇。参见\"屏摄\"。\n摄zhé 1.折叠。 2.见\"摄叶\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-摄"},{"id":"glyph-seal-6447","script":"seal","character":"摇","reading":"yáo","description":"yáo：(1)摆动～曳。～晃。～荡。～篮。动～。～摆。～头摆尾。～～欲坠。扶～直上。\n(2)往上升风举云～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-摇"},{"id":"glyph-seal-6448","script":"seal","character":"摈","reading":"bìn","description":"排斥;弃绝\n通傧”。导引宾客\n摈 bìn废弃；排开。\n【摈弃】抛弃。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-摈"},{"id":"glyph-seal-644a","script":"seal","character":"摊","reading":"tān","description":"摊派\n把糊状食物倒在锅中使成为薄片\n摊 〈名〉\n摊子\n古代\n⒈展开，摆开～开。把意见～出来。\n⒉将糊状物放在热锅里铺成薄片煎熟～饼。～鸡蛋。\n⒊分派，分担～派。分～。\n⒋路旁或街旁摆的售货处书～。地～子。菜～儿。水果～。\n⒌凝集成一片一～水。一～稀泥。\n⒍遇到，碰上他～上了好事。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-摊"},{"id":"glyph-seal-6458","script":"seal","character":"摘","reading":"zhāi","description":"zhāi：(1)采取，拿下采～。～取。～桃子。～除。\n(2)选取～要。～录。～编。文～。～引。寻章～句。指～（挑出缺点）。\n(3)借～兑。东～西借。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-摘"},{"id":"glyph-seal-6467","script":"seal","character":"摧","reading":"cuī","description":"cuī：(1)破坏，折断～残。～折。～颓。～眉折腰。\n(2)挫败，挫折～败。～挫。～陷。\n(3)伤痛～怆。～心。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-摧"},{"id":"glyph-seal-6469","script":"seal","character":"摩","reading":"mó；mā","description":"mó：(1)擦，蹭，接触～擦。～天。～崖（山崖上刻的文字、佛像等）。～肩接踵。～顶放踵。\n(2)摸，抚～弄。～挲（suō）\n(3)研究，切磋观～。揣～（a.研究，仔细琢磨；b.估量，推测）。\n(4)古同磨”，磨擦。\nmā：〔～挲（sɑ）〕用手轻轻按着一下一下地移动。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-摩"},{"id":"glyph-seal-646d","script":"seal","character":"摭","reading":"zhí","description":"zhí：拾取，摘取～拾。采～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-摭"},{"id":"glyph-seal-6479","script":"seal","character":"摹","reading":"mó","description":"mó：仿效，照着样子做～仿（亦作模仿”）。～刻。～拟（亦作模拟”）。～写（亦作模写”）。～状。～印。临～。描～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-摹"},{"id":"glyph-seal-647d","script":"seal","character":"摽","reading":"biāo；biào","description":"biào：(1)紧紧地捆绑物体使其相连椅子腿活动了，用铁丝～住。\n(2)比着～着劲干。\n(3)用胳膊紧紧地钩住他俩～着胳膊走。\n(4)亲近，依附（多含贬义）他们～在一块儿。\n(5)落～梅。\n(6)打，击长木之毙，无不～也”。\n(7)捶胸的样子静言思之，寤辟有～”。\nbiāo：(1)挥之使动曹子～剑而去之”。\n(2)高扬～然若秋云之远”。\n(3)古同标”，标榜。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-摽"},{"id":"glyph-seal-6485","script":"seal","character":"撅","reading":"juē；jué","description":"juē：(1)翘起～嘴。～尾巴。小辫～着。\n(2)折断把竹竿～折（shé）了。\njué：古同掘”，控掘。\n〔～竖〕眼光浅，才识短，如～～小人，无大经略”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-撅"},{"id":"glyph-seal-6487","script":"seal","character":"撇","reading":"piě；piē","description":"piē：(1)丢开，抛弃～开。～弃。\n(2)由液体表面舀染粥时把沫儿～掉。\npiě：(1)平着向前扔～手榴弹。\n(2)汉字笔形之一，由上向左而斜下。\n(3)像汉字的撇形的～嘴。两～黑眉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-撇"},{"id":"glyph-seal-649e","script":"seal","character":"撞","reading":"zhuàng","description":"zhuàng：(1)冲打，碰击～钟。～车。～击。顶～。冲～。\n(2)碰见，无意中遇到～见。\n(3)试探～大运（碰运气）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-撞"},{"id":"glyph-seal-64a9","script":"seal","character":"撩","reading":"liáo；liāo","description":"liāo：(1)掀起～起衣襟。～起头发。\n(2)用手舀着洒水先～水后扫地。\nliáo：挑弄，引逗～拨。～乱（纷乱，如眼花～～”。亦作缭乱”）。春色～人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-撩"},{"id":"glyph-seal-64ad","script":"seal","character":"播","reading":"bō","description":"bō：(1)撒种～种（zhǒng）。～种（zhòng）（用撒布种子的方式种植）。～撒。夏～。春～。\n(2)传扬，传布广～。传～。～音。～发。～弄。～扬（a.宣扬，传扬；b.发动）。～放。～映。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-播"},{"id":"glyph-seal-64ae","script":"seal","character":"撮","reading":"cuō；zuǒ","description":"cuō：(1)聚起，多指用簸箕状的器具铲起东西～成一堆。～土。～合。\n(2)取，摘取～要。\n(3)用手指捏取细碎的东西～药。\n(4)中国市制容量单位，一升的千分之一。\n(5)量词一～米。\n(6)撮东西用的器具～子。～箕。\nzuǒ：量词，用于成丛的毛发剪下一～头发。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-撮"},{"id":"glyph-seal-64b7","script":"seal","character":"撷","reading":"xié","description":"同襭”。把衣襟掖在腰带上以兜东西\n⒈摘取采～。\n⒉使用衣襟兜东西。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-撷"},{"id":"glyph-seal-64c5","script":"seal","character":"擅","reading":"shàn","description":"shàn：(1)超越职权，自作主张～专。～自。～行（xíng）。～断（专行）。专～独行。～离职守。\n(2)独揽，占有～权。～利。～兵（拥有兵权）。～国。～美。\n(3)长（cháng）于，善于～长（cháng）。不～辞令。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-擅"},{"id":"glyph-seal-64cd","script":"seal","character":"操","reading":"cāo","description":"cāo：(1)拿，抓在手里～刀。～觚（手持木简，指写诗作文）。～管（执笔，指写作）。～刀必割（喻不失时机，要当机立断）。\n(2)控制、掌握～舟。～纵。\n(3)从事～心。～办。～作。～持。～劳。～之过急。\n(4)体力的锻炼，军事的训练～练。～场。～演。上～。\n(5)用某种语言或方言讲话他～一口闽南音。\n(6)行为，品行～行。～守。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-操"},{"id":"glyph-seal-64d2","script":"seal","character":"擒","reading":"qín","description":"qín：捉拿～拿。生～。就～。欲～故纵。～贼先～王。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-擒"},{"id":"glyph-seal-64d8","script":"seal","character":"擘","reading":"bò；bāi","description":"bò：大拇指～画（计划，布置。亦作擘划”）。～窠（指在印章或石碑上用直线划出来的方格子，以使刻写的字整齐）。巨～（喻杰出的人物）。～肌分理（喻分析事理很缜密）。\nbāi：同掰”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-擘"},{"id":"glyph-seal-64e2","script":"seal","character":"擢","reading":"zhuó","description":"zhuó：(1)拔～发（fà）难（nán）数（shǔ）（喻罪恶多得像头发那样数不清）。\n(2)提拔，提升～升。～用。～第。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-擢"},{"id":"glyph-seal-6500","script":"seal","character":"攀","reading":"pān","description":"pān：(1)抓住东西向上爬～登。～高。～越。～桂（古代指科举考试登第）。～折（zhé）。～附。～援。\n(2)拉扯，拉拢，结交～交。～扯。～谈。～亲。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-攀"},{"id":"glyph-seal-6518","script":"seal","character":"攘","reading":"rǎng","description":"rǎng：(1)侵夺，偷窃～羊（指暴露亲人的过失，语出《论语??子路》中的耳父～～，而子证之”）。～夺。～窃。～善（掠人之美）。\n(2)推，排斥～斥。～除。～夷（抵御外国侵略）。\n(3)烦乱～～（纷乱）。扰～。\n(4)捋～袂。～臂。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-攘"},{"id":"glyph-seal-652b","script":"seal","character":"攫","reading":"jué","description":"jué：抓取～取（掠夺）。～夺。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-攫"},{"id":"glyph-seal-652f","script":"seal","character":"支","reading":"zhī","description":"zhī：(1)撑持，伸出，竖起～撑。～援。体力不～。\n(2)受得住乐不可～。\n(3)领款或付款～付。\n(4)调度，指使～使。～应。～着儿。\n(5)附属于总体的一个部分总～。～流。～离。\n(6)量词一～笔。\n〔地～〕历法中用的十二个字子丑寅卯辰巳午未申酉戌亥。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-支"},{"id":"glyph-seal-6536","script":"seal","character":"收","reading":"shōu","description":"shōu：(1)接到，接受～发。～信。～支。～讫。～益。\n(2)藏或放置妥当这是重要东西，要～好了。\n(3)割断成熟的农作物～割。～成。麦～。\n(4)招回～兵。～港。\n(5)聚，合拢～容。～理。～集。\n(6)结束～尾。～煞。～盘。\n(7)逮捕，拘押～捕。～监。～押。～审。\n(8)约束，控制（感情或行动）～束。～心。～伏（亦作收服”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-收"},{"id":"glyph-seal-6538","script":"seal","character":"攸","reading":"yōu","description":"yōu：(1)所性命～关。\n(2)疾走的样子～然而逝。\n(3)水流的样子河水～～。\n(4)文言语助词，无义四方～同”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-攸"},{"id":"glyph-seal-6539","script":"seal","character":"改","reading":"gǎi","description":"gǎi：(1)变更，更换～变。更（gēng）～。～革。～造。～善。～弦更张。朝令夕～。～编。～写。纂～。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-改"},{"id":"glyph-seal-653b","script":"seal","character":"攻","reading":"gōng","description":"gōng：(1)打击，与守”相对～击。～占。～取。～心。～关。～陷。\n(2)指责，驳斥～难（nàn）。群起而～之。\n(3)治病以毒～毒。\n(4)致力学习或研究～读。～书。专～医学。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-攻"},{"id":"glyph-seal-653e","script":"seal","character":"放","reading":"fàng","description":"fàng：(1)解脱约束，得到自由把笼子里的鸟～了。～胆。～诞。～任。～肆。～歌。～怀±～。释～。\n(2)散（sàn）～工。～假。～学。～晴（阴雨后转晴）。\n(3)带牲畜到野外去吃草～牧。～羊（亦喻任其自由行动，放手不管，含贬义）。\n(4)驱逐到远方去～逐。～黜。流～。\n(5)到基层去～官（古时指任命为外地官员）。下～。\n(6)发出～电。～毒。～光。发～。\n(7)借钱给别人，收取利息～债。～贷。\n(8)扩展～大。～宽。\n(9)花开百花齐～。心花怒～。\n(10)搁、置这件事情不要紧，先～一～。存～。～弃。～心。～置。\n(11)至～乎四海。摩顶～踵。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-放"},{"id":"glyph-seal-653f","script":"seal","character":"政","reading":"zhèng","description":"zhèng：(1)治理国家事务～治。～府。～党。～权。～纲。～策。～令。～绩。～见。～客（为个人或某一集团利益从事政治活动的人）。～局。～变。参～。议～。\n(2)国家某一部门主管的业务财～。邮～。民～。\n(3)家庭或集体生活中的事务家～。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-政"},{"id":"glyph-seal-6545","script":"seal","character":"故","reading":"gù","description":"gù：(1)意外的事情事～。变～。～障。\n(2)原因缘～。原～。\n(3)有心，存心～意。～杀（有意谋杀）。明知～犯。\n(4)老，旧，过去的，原来的～事（a.旧事，成例；b.有连贯性的比较完整的事情，比较适合于口头讲述，事”读轻声）。～人。～乡。～土（故乡）。～园（故乡）。～居。～国（故乡，亦指祖国）。～纸堆（泛指旧而多的文籍）。革～鼎新（革”，除去；鼎”，更新；破除旧的，建立新的）。～步自封（故步”，原来的步子；封”，限制；喻安于现状，不求进取。亦作固步自封”）。\n(5)朋友，友情亲～。沾亲带～。\n(6)死亡（指人）～去。病～。\n(7)所以，因此～此。～而。\n(8)古同顾”，反而。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-故"},{"id":"glyph-seal-6548","script":"seal","character":"效","reading":"xiào","description":"xiào：(1)摹仿～法。仿～。上行下～。～尤（明知别人的行为是错的而照样去做）。\n(2)功用，成果～验。～果。成～。有～。功～。～益。～用。～应。～率（lǜ）。\n(3)尽、致～力。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-效"},{"id":"glyph-seal-654c","script":"seal","character":"敌","reading":"dí","description":"抵抗;抵挡\n攻击\n①仇敌～人、抗～。\n②对抗；抵拒所向无～。\n③同等；相当势均力～。\n【敌敌畏】〈外〉一种有机磷杀虫剂，为稍带芳香臭体的无色透明液体。\n【敌酋】敌人的头子。\n【敌人】敌对的人或敌对的方面。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-敌"},{"id":"glyph-seal-654f","script":"seal","character":"敏","reading":"mǐn","description":"mǐn：(1)迅速，灵活～捷。～感。～锐。～达（敏捷而通达事理）。灵～。聪～。神经过～。\n(2)奋勉～求（勉力以求）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-敏"},{"id":"glyph-seal-6551","script":"seal","character":"救","reading":"jiù","description":"jiù：(1)给予帮助使脱离危险或解脱困难～济。～命。～护。～国。～难（nàn）。～灾。～药。～正（补救匡正）。～死扶伤。～困扶危。\n(2)终止濯以～热。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-救"},{"id":"glyph-seal-6555","script":"seal","character":"敕","reading":"chì","description":"chì：(1)帝王的诏书、命令～命。～书。～封。奉～。宣～。\n(2)告诫申～。戒～。\n(3)古同饬”，整顿。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-敕"},{"id":"glyph-seal-6556","script":"seal","character":"敖","reading":"áo","description":"áo：(1)出游，闲游以～以游”。\n(2)古同熬”，煎熬。\n(3)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-敖"},{"id":"glyph-seal-6559","script":"seal","character":"教","reading":"jiāo；jiào","description":"jiāo：把知识或技能传授给人。jiào：教育、教导；宗教，如教学、教诲、佛教。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-655b","script":"seal","character":"敛","reading":"liǎn","description":"收获\n征收\n豹因重敛百姓\n⒈收，聚集收～。聚～。秋～冬藏。〈引〉征收横征暴～。\n⒉约束，检点～迹。闭门自～。\n敛lián 1.见\"敛盂\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-敛"},{"id":"glyph-seal-655d","script":"seal","character":"敝","reading":"bì","description":"bì：(1)破旧，坏～旧。～俗。～衣。～屣。～帚自珍。\n(2)谦辞，用于与自己有关的事物～人（我）。～姓。～处。～校。～国。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-敝"},{"id":"glyph-seal-655e","script":"seal","character":"敞","reading":"chǎng","description":"chǎng：(1)（房屋、庭院等）没有遮蔽～亮。宽～。\n(2)张开，打开～着大门。～篷马车。～开供应。\n(3)古同畅”，畅快。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-敞"},{"id":"glyph-seal-6562","script":"seal","character":"敢","reading":"gǎn","description":"gǎn：(1)有勇气，有胆量勇～。果～。～闯。～死队。～作～为。～怒而不～言。\n(2)谦辞，不敢”的简称，冒昧的意思～问。～请。～烦。\n(3)方言，莫非～许。～怕。～是哥哥回来了？","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-敢"},{"id":"glyph-seal-6563","script":"seal","character":"散","reading":"sàn；sǎn","description":"sàn：(1)分开，由聚集而分离分～。解～。涣～。～落。～失。～逸。\n(2)分布，分给～布。～发（fā）。天女～花。\n(3)排遣～心。～闷（mèn）。\n(4)解雇他干的不好，让那家饭店给～了。\n集；聚；\nsǎn：(1)没有约束，松开松～。～漫。懒～。～曲。～记。～板。～文。披～头发。\n(2)分开的，分离的～居。～乱。～座。～兵游勇。\n(3)零碎的～碎。～装。～页。\n(4)中医称药末～剂。丸～膏丹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-散"},{"id":"glyph-seal-6566","script":"seal","character":"敦","reading":"dūn；duì","description":"dūn：(1)厚道，笃厚～朴。～厚。～实。\n(2)诚心诚意～聘。～请。\n(3)督促使虞～匠”。～劝。～促。\n(4)姓。\nduì：古代盛黍稷的器具。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-敦"},{"id":"glyph-seal-656b","script":"seal","character":"敫","reading":"jiǎo","description":"jiǎo：姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-敫"},{"id":"glyph-seal-656c","script":"seal","character":"敬","reading":"jìng","description":"jìng：(1)尊重，有礼貌地对待尊～。致～。～重（zhòng）。～爱。～仰。恭～。～辞。～慕。～献。\n(2)表示敬意的礼物喜～。寿～。\n(3)有礼貌地送上去～酒。～香。\n(4)谨慎，不怠慢慎始～终（自始自终都谨慎不懈）。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-敬"},{"id":"glyph-seal-6570","script":"seal","character":"数","reading":"shù；shǔ；shuò","description":"shù：数目、数量；几，几个。shǔ：计算数目；列举、责备。shuò：屡次，如数见不鲜。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-6572","script":"seal","character":"敲","reading":"qiāo","description":"qiāo：打，击～打。～击。～诈。～边鼓（喻从旁帮人说话）。～门砖。～骨吸髓。旁～侧击。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-敲"}];
